'@
$pack = Join-Path $work 'r57_pin_source.zip'
[System.IO.File]::WriteAllBytes($pack,[System.Convert]::FromBase64String(($payload -replace '\s','')))
$actualHash = (Get-FileHash -LiteralPath $pack -Algorithm SHA256).Hash.ToUpperInvariant()
if ($actualHash -ne '1044E88069C398533D3BABBF242CC01251AB19BED7661298628F0DA912BCF7F7') { throw 'R57_EMBEDDED_SOURCE_SHA_DRIFT' }
Expand-Archive -LiteralPath $pack -DestinationPath $work -Force
$log = Join-Path $work 'R57_CONSOLE.log'
$exitcode=1
Write-Host 'R57_MODE=INDEPENDENT_EVENT_BROKER_HISTORICAL_ONLY_NO_2024_NO_LIVE_NO_PRODUCTION'
try {
  & $py (Join-Path $work 'r57_event_broker.py') --repo $repo --downloads $downloads --work $work --out $out --pin (Join-Path $work 'R54_P0R5_EVENT_CENSUS_REPORT_PIN.json') --evidence (Join-Path $work 'R56_FROZEN_EVIDENCE.zip') 2>&1 | Tee-Object -FilePath $log
  $exitcode = $LASTEXITCODE
} catch {
  ($_ | Out-String) | Set-Content -Path (Join-Path $out 'R57_WRAPPER_EXCEPTION.txt') -Encoding UTF8
  Write-Host ('R57_WRAPPER_EXCEPTION=' + $_.Exception.Message)
  $exitcode = 1
} finally {
  if (Test-Path -LiteralPath $log) {Copy-Item -LiteralPath $log -Destination (Join-Path $out 'R57_CONSOLE.log') -Force}
  $packet = Join-Path $downloads ('UPLOAD_THIS_AKAH_R57_INDEPENDENT_BROKER_' + $stamp + '.zip')
  Compress-Archive -Path (Join-Path $out '*') -DestinationPath $packet -CompressionLevel Optimal -Force
  Write-Host ('R57_UPLOAD_THIS=' + $packet)
  Write-Host ('R57_EXIT_CODE=' + $exitcode)
}
exit $exitcode
